
`timescale 1ps/1ps

module axi_protocol_converter_merge_ba32972ac42e #(
  parameter  AL_US_AXI_PROTOCOL            = 0,//0:AXI4  1:AXI3   2:AXI Lite 
  parameter  AL_DS_AXI_PROTOCOL            = 2, 

  parameter  AL_AXI_ID_WIDTH              = 4,
  parameter  AL_AXI_ADDR_WIDTH            = 32,
  parameter  AL_AXI_DATA_WIDTH            = 32,
  parameter  AL_AXI_SUPPORTS_WRITE        = 1,
  parameter  AL_AXI_SUPPORTS_READ         = 1,
  parameter  AL_AXI_SUPPORTS_USER_SIGNALS = 1,
                     // 1 = Propagate all USER signals, 0 = Don’t propagate.
  parameter  AL_AXI_AWUSER_WIDTH          = 1,
  parameter  AL_AXI_ARUSER_WIDTH          = 1,
  parameter  AL_AXI_WUSER_WIDTH           = 1,
  parameter  AL_AXI_RUSER_WIDTH           = 1,
  parameter  AL_AXI_BUSER_WIDTH           = 1

 )(
  // Global Signals
   input wire aclk,
   input wire aresetn,

   // Slave Interface Write Address Ports
   input  wire [AL_AXI_ID_WIDTH-1:0]     us_axi_awid,
   input  wire [AL_AXI_ADDR_WIDTH-1:0]   us_axi_awaddr,
   input  wire [((AL_US_AXI_PROTOCOL == 1) ? 4 : 8)-1:0]  us_axi_awlen,
   input  wire [3-1:0]                  us_axi_awsize,
   input  wire [2-1:0]                  us_axi_awburst,
   input  wire [((AL_US_AXI_PROTOCOL == 1) ? 2 : 1)-1:0]  us_axi_awlock,
   input  wire [4-1:0]                  us_axi_awcache,
   input  wire [3-1:0]                  us_axi_awprot,
   input  wire [4-1:0]                  us_axi_awregion,
   input  wire [4-1:0]                  us_axi_awqos,
   input  wire [AL_AXI_AWUSER_WIDTH-1:0] us_axi_awuser,
   input  wire                          us_axi_awvalid,
   output wire                          us_axi_awready,

   // Slave Interface Write Data Ports
   input wire [AL_AXI_ID_WIDTH-1:0]      us_axi_wid,
   input  wire [AL_AXI_DATA_WIDTH-1:0]   us_axi_wdata,
   input  wire [AL_AXI_DATA_WIDTH/8-1:0] us_axi_wstrb,
   input  wire                          us_axi_wlast,
   input  wire [AL_AXI_WUSER_WIDTH-1:0]  us_axi_wuser,
   input  wire                          us_axi_wvalid,
   output wire                          us_axi_wready,

   // Slave Interface Write Response Ports
   output wire [AL_AXI_ID_WIDTH-1:0]    us_axi_bid,
   output wire [2-1:0]                 us_axi_bresp,
   output wire [AL_AXI_BUSER_WIDTH-1:0] us_axi_buser,
   output wire                         us_axi_bvalid,
   input  wire                         us_axi_bready,

   // Slave Interface Read Address Ports
   input  wire [AL_AXI_ID_WIDTH-1:0]     us_axi_arid,
   input  wire [AL_AXI_ADDR_WIDTH-1:0]   us_axi_araddr,
   input  wire [((AL_US_AXI_PROTOCOL == 1) ? 4 : 8)-1:0]  us_axi_arlen,
   input  wire [3-1:0]                  us_axi_arsize,
   input  wire [2-1:0]                  us_axi_arburst,
   input  wire [((AL_US_AXI_PROTOCOL == 1) ? 2 : 1)-1:0]  us_axi_arlock,
   input  wire [4-1:0]                  us_axi_arcache,
   input  wire [3-1:0]                  us_axi_arprot,
   input  wire [4-1:0]                  us_axi_arregion,
   input  wire [4-1:0]                  us_axi_arqos,
   input  wire [AL_AXI_ARUSER_WIDTH-1:0] us_axi_aruser,
   input  wire                          us_axi_arvalid,
   output wire                          us_axi_arready,

   // Slave Interface Read Data Ports
   output wire [AL_AXI_ID_WIDTH-1:0]    us_axi_rid,
   output wire [AL_AXI_DATA_WIDTH-1:0]  us_axi_rdata,
   output wire [2-1:0]                 us_axi_rresp,
   output wire                         us_axi_rlast,
   output wire [AL_AXI_RUSER_WIDTH-1:0] us_axi_ruser,
   output wire                         us_axi_rvalid,
   input  wire                         us_axi_rready,
   
   // Master Interface Write Address Port
   output wire [AL_AXI_ID_WIDTH-1:0]     ds_axi_awid,
   output wire [AL_AXI_ADDR_WIDTH-1:0]   ds_axi_awaddr,
   output wire [((AL_DS_AXI_PROTOCOL == 1) ? 4 : 8)-1:0]  ds_axi_awlen,
   output wire [3-1:0]                  ds_axi_awsize,
   output wire [2-1:0]                  ds_axi_awburst,
   output wire [((AL_DS_AXI_PROTOCOL == 1) ? 2 : 1)-1:0]  ds_axi_awlock,
   output wire [4-1:0]                  ds_axi_awcache,
   output wire [3-1:0]                  ds_axi_awprot,
   output wire [4-1:0]                  ds_axi_awregion,
   output wire [4-1:0]                  ds_axi_awqos,
   output wire [AL_AXI_AWUSER_WIDTH-1:0] ds_axi_awuser,
   output wire                          ds_axi_awvalid,
   input  wire                          ds_axi_awready,
   
   // Master Interface Write Data Ports
   output wire [AL_AXI_ID_WIDTH-1:0]     ds_axi_wid,
   output wire [AL_AXI_DATA_WIDTH-1:0]   ds_axi_wdata,
   output wire [AL_AXI_DATA_WIDTH/8-1:0] ds_axi_wstrb,
   output wire                          ds_axi_wlast,
   output wire [AL_AXI_WUSER_WIDTH-1:0]  ds_axi_wuser,
   output wire                          ds_axi_wvalid,
   input  wire                          ds_axi_wready,
   
   // Master Interface Write Response Ports
   input  wire [AL_AXI_ID_WIDTH-1:0]    ds_axi_bid,
   input  wire [2-1:0]                 ds_axi_bresp,
   input  wire [AL_AXI_BUSER_WIDTH-1:0] ds_axi_buser,
   input  wire                         ds_axi_bvalid,
   output wire                         ds_axi_bready,
   
   // Master Interface Read Address Port
   output wire [AL_AXI_ID_WIDTH-1:0]     ds_axi_arid,
   output wire [AL_AXI_ADDR_WIDTH-1:0]   ds_axi_araddr,
   output wire [((AL_DS_AXI_PROTOCOL == 1) ? 4 : 8)-1:0]  ds_axi_arlen,
   output wire [3-1:0]                  ds_axi_arsize,
   output wire [2-1:0]                  ds_axi_arburst,
   output wire [((AL_DS_AXI_PROTOCOL == 1) ? 2 : 1)-1:0]  ds_axi_arlock,
   output wire [4-1:0]                  ds_axi_arcache,
   output wire [3-1:0]                  ds_axi_arprot,
   output wire [4-1:0]                  ds_axi_arregion,
   output wire [4-1:0]                  ds_axi_arqos,
   output wire [AL_AXI_ARUSER_WIDTH-1:0] ds_axi_aruser,
   output wire                          ds_axi_arvalid,
   input  wire                          ds_axi_arready,
   
   // Master Interface Read Data Ports
   input  wire [AL_AXI_ID_WIDTH-1:0]    ds_axi_rid,
   input  wire [AL_AXI_DATA_WIDTH-1:0]  ds_axi_rdata,
   input  wire [2-1:0]                 ds_axi_rresp,
   input  wire                         ds_axi_rlast,
   input  wire [AL_AXI_RUSER_WIDTH-1:0] ds_axi_ruser,
   input  wire                         ds_axi_rvalid,
   output wire                         ds_axi_rready
);

